/*
 * A333485  Heinz numbers of all integer partitions sorted first by sum, then
 *          by decreasing length, and finally lexicographically. A code for
 *          the Fenner-Loizou tree A228100.
 * https://oeis.org/A333485
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, look, tabf
 * Formula:   A333485 – Heinz numbers of integer partitions sorted by sum,
 *            decreasing length, and lexicographic order. The sequence is
 *            generated by constructing partitions in that order and computing
 *            the product of the primes indexed by the parts
 * Range:     u8 n <= 44, u16 n <= 683, u32 n <= 9295, u64 n <= 9295,
 *            u128 n <= 9295, big any n
 * Validated: standard, pass, 83 terms through n = 7673 (2026-11-03)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stddef.h>
#include <stdbool.h>
#include "../utils/mem.h"

/* Return the k‑th prime (k ≥ 1).  On first call the prime list
   is built incrementally using trial division.  The list is
   stored in a static array which is expanded as necessary.   */
static uint32_t get_prime(idx_t k)
{
    static uint32_t *pr = NULL;     /* array of primes */
    static size_t sz   = 0;         /* number of primes stored */
    static size_t cap  = 0;         /* allocated capacity */
    static uint32_t cand = 3;       /* candidate after 2 */

    /* initialise the prime table on first use */
    if (sz == 0) {
        cap = 8;
        pr = (uint32_t *)realloc(pr, cap * sizeof(uint32_t));
        if (!pr) abort();
        sz = 0;
    }

    /* grow the array until we have at least k primes */
    while (sz < (size_t)k) {
        if (sz == 0) {                /* add the first prime */
            pr[sz++] = 2;
            continue;
        }

        /* find the next prime candidate */
        uint32_t p = cand;
        bool ok = true;
        for (size_t i = 0; i < sz; ++i) {
            uint32_t prime = pr[i];
            if ((uint64_t)prime * prime > (uint64_t)p) break;
            if (p % prime == 0) { ok = false; break; }
        }

        if (!ok) {                    /* not prime – keep searching */
            cand += 2;                /* only odd numbers remain */
            continue;
        }

        /* prime found – store it, grow table if needed */
        if (sz == cap) {
            cap <<= 1;
            pr = (uint32_t *)realloc(pr, cap * sizeof(uint32_t));
            if (!pr) abort();
        }
        pr[sz++] = p;
        cand = p + 2;
    }

    return pr[(size_t)k - 1];
}

static seq_t *cache = NULL;
static size_t cached = 0;
static size_t cap = 0;
static idx_t next_sum = 0;

static inline void add_term(seq_t value) {
    if (cached == cap) {
        size_t new_cap = (cap == 0) ? 16 : cap << 1;
        seq_t *tmp = mem_resize(seq_t, cache, new_cap);
        if (!tmp) abort();
        cache = tmp;
        cap = new_cap;
    }
    cache[cached++] = value;
}

static void dfs(idx_t rem, idx_t parts_left, idx_t max_allowed, seq_t prod) {
    if (parts_left == 0) {
        if (rem == 0) add_term(prod);
        return;
    }
    if (rem < parts_left) return;

    idx_t min_part = (rem + parts_left - 1) / parts_left;
    if (min_part > max_allowed) return;

    idx_t max_part = rem - (parts_left - 1);
    if (max_part > max_allowed) max_part = max_allowed;

    for (idx_t p = min_part; p <= max_part; ++p) {
        seq_t new_prod = prod * (seq_t)get_prime(p);
        dfs(rem - p, parts_left - 1, p, new_prod);
    }
}

static void ensure_cache(idx_t n) {
    while (cached <= n) {
        if (next_sum == 0) {           /* empty partition */
            add_term((seq_t)1);
            ++next_sum;
            continue;
        }
        idx_t s = next_sum;
        for (idx_t len = s; len >= 1; --len) {
            dfs(s, len, s, (seq_t)1);
        }
        ++next_sum;
    }
}

seq_t a(idx_t n) {
    ensure_cache(n);
    return cache[n];
}
